#include <bits/stdc++.h>
using namespace std;
int main(){
    int T;
    scanf("%d", &T);
    while(T--){
        int a,b,c,d;
        scanf("%d %d %d %d", &a, &b, &c, &d);
        vector<vector<int>> dist(a+1, vector<int>(b+1, INT_MAX));
        dist[0][0] = 0;
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;
        pq.push({0,0,0});
        int bestD = -1, bestCost = INT_MAX;
        auto consider = [&](int amt, int cost){
            if (amt > d) return;
            if (amt > bestD || (amt == bestD && cost < bestCost)) { bestD = amt; bestCost = cost; }
        };
        vector<vector<bool>> done(a+1, vector<bool>(b+1,false));
        while(!pq.empty()){
            auto [cost,x,y] = pq.top(); pq.pop();
            if (done[x][y]) continue;
            done[x][y] = true;
            int z = c - x - y;
            consider(x, cost); consider(y, cost); consider(z, cost);
            int cap[3] = {a,b,c};
            int cur[3] = {x,y,z};
            for (int i=0;i<3;i++) for(int j=0;j<3;j++){
                if (i==j) continue;
                int pour = min(cur[i], cap[j]-cur[j]);
                if (pour <= 0) continue;
                int ncur[3] = {cur[0],cur[1],cur[2]};
                ncur[i]-=pour; ncur[j]+=pour;
                int nx=ncur[0], ny=ncur[1];
                if (nx<0||nx>a||ny<0||ny>b) continue;
                int ncost = cost+pour;
                if (ncost < dist[nx][ny]) { dist[nx][ny]=ncost; pq.push({ncost,nx,ny}); }
            }
        }
        printf("%d %d\n", bestCost, bestD);
    }
}

